body:
`c2go` incorrectly translates a C union initializer into a Go struct literal.
In C, `union Number n = {42};` initializes the first member of the union. However, `c2go` represents the union as a Go struct containing `memory unsafe.Pointer`, and then incorrectly emits `Number{int32(42)}`. This attempts to initialize the `unsafe.Pointer` field with an `int32` value, producing invalid Go code.
**To Reproduce**
```c
#include <stdio.h>

union Number {
    int i;
};

int main(void) {
    union Number n = {42};

    printf("%d\n", n.i);
    return 0;
}
```
**Generated Go Code**
```go
type Number struct{ memory unsafe.Pointer }

func (unionVar *Number) copy() Number {
        var buffer [8]byte
        for i := range buffer {
                buffer[i] = (*((*[8]byte)(unionVar.memory)))[i]
        }
        var newUnion Number
        newUnion.memory = unsafe.Pointer(&buffer)
        return newUnion
}

func (unionVar *Number) i() *int32 {
        if unionVar.memory == nil {
                var buffer [8]byte
                unionVar.memory = unsafe.Pointer(&buffer)
        }
        return (*int32)(unionVar.memory)
}

func main() {
        var n Number = Number{int32(42)}
        noarch.Printf((&[]byte("%d\n\x00")[0]), (*n.i()))
        return
}
```
**Observed Behavior**
```
# command-line-arguments
./test.go:183:24: cannot use int32(42) (constant 42 of type int32) as unsafe.Pointer value in struct literal
```
